require_once __DIR__.'/../../includes/accounting_ui.php';$result=null;
if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&($_POST['action']??'')==='generate')try{if(empty($_POST['confirm']))throw new InvalidArgumentException('Confirm recurring subscription bill generation.');$result=$ac->generateSubscriptions($_POST['date']??'');}catch(InvalidArgumentException $e){$error=$e->getMessage();}
elseif(($_SERVER['REQUEST_METHOD']??'')==='POST')acHandle(function()use($ac){if(($_POST['action']??'')==='create')return $ac->saveSubscription($_POST);$ac->changeSubscription((int)($_POST['subscription_id']??0),$_POST['status']??'',$_POST['date']??'');},'subscriptions');
$items=$ac->rows('SELECT id,name FROM ac_items WHERE school_id=? AND is_active=1 ORDER BY name',[$school]);ob_start();
?>
<p>Subscriptions use catalog services and existing students or external customers. Paused/cancelled subscriptions are not billed; end dates are enforced. Scheduling uses the documented CLI, not an unconfigured background service.</p>
<?php if($result): ?><div class="alert <?= $result['errors']?'alert-warning':'alert-success' ?>">Generated <?= count($result['issued']) ?> bills. <?php foreach($result['errors'] as $e): ?>Subscription <?= (int)$e['subscription'] ?>: <?= sanitize($e['error']) ?>. <?php endforeach; ?></div><?php endif; ?>
<?php if($ac->can('invoice')): ?><details class="mb-3"><summary class="btn btn-primary">Create subscription</summary><?php acForm('create');acSelect('item_id','Catalog service / product',$items);acStudentPicker();acInput('customer_name','External customer name (not required for student)','','text',false);acSelect('frequency','Frequency',acChoices(['monthly'=>'Monthly','quarterly'=>'Quarterly','annual'=>'Annual','one_time'=>'One time']),'monthly');acInput('amount','Cycle amount (NPR)','0.00','number');acInput('start_date','Start date',date('Y-m-d'),'date');acInput('end_date','End date','','date',false); ?><label><input type="checkbox" name="renewal" value="1"> Renewal reminders enabled (external delivery disabled until configured)</label><?php acSubmit('Save subscription'); ?></details>
<?php acForm('generate','Generate due subscription bills');acInput('date','Bill cycles due through',date('Y-m-d'),'date'); ?><label><input type="checkbox" required name="confirm" value="1"> Confirm billing of active, due subscriptions</label><?php acSubmit('Generate due bills'); ?><?php endif; ?>
<div class="card card-body table-responsive"><table class="table"><thead><tr><th>Service</th><th>Customer</th><th>Amount</th><th>Frequency</th><th>Next date</th><th>End date</th><th>Status</th><th>Change</th></tr></thead><tbody><?php foreach($ac->rows('SELECT s.*,i.name FROM ac_subscriptions s JOIN ac_items i ON i.id=s.item_id WHERE s.school_id=? ORDER BY s.id DESC',[$school]) as $s): ?><tr><td><?= sanitize($s['name']) ?></td><td><?= sanitize($s['customer_name']) ?></td><td><?= acMoney((int)$s['amount_minor']) ?></td><td><?= sanitize($s['frequency']) ?></td><td><?= sanitize(schoolDateLabel($s['next_date'],'both','ymd')) ?></td><td><?= sanitize($s['end_date']??'No end date') ?></td><td><?= sanitize($s['status']) ?></td><td><?php if($ac->can('invoice')&&!in_array($s['status'],['cancelled','expired'],true)): ?><form method="post"><input type="hidden" name="action" value="status"><input type="hidden" name="subscription_id" value="<?= $s['id'] ?>"><input type="hidden" name="date" value="<?= date('Y-m-d') ?>"><?php acSelect('status','Status',acChoices(['active'=>'Resume','paused'=>'Pause','cancelled'=>'Cancel']),$s['status']); ?><button class="btn btn-sm btn-secondary">Update</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php acRender('Subscription billing',ob_get_clean());
